<script setup lang="ts">
import{ref,onMounted,onBeforeUnmount}from'vue';import{locale}from'../i18n';
const tr=(a:string,b:string)=>locale.value==='id'?a:b;const file=ref<File|null>(null),preview=ref(''),version=ref(0),reviewed=ref(false),busy=ref(false),message=ref('');
onMounted(async()=>{try{const r=await fetch('/platform/branding',{credentials:'same-origin',signal:AbortSignal.timeout(15000)});if(!r.ok)return;const d=await r.json();version.value=d.version;preview.value=d.url??'';}catch{message.value=tr('Logo belum dapat dimuat.','Unable to load logo.');}});
onBeforeUnmount(()=>{if(preview.value.startsWith('blob:'))URL.revokeObjectURL(preview.value);});
function choose(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>1048576){message.value=tr('Gunakan PNG/JPEG/WebP maksimal 1 MB.','Use PNG/JPEG/WebP up to 1 MB.');return;}if(preview.value.startsWith('blob:'))URL.revokeObjectURL(preview.value);file.value=f;preview.value=URL.createObjectURL(f);reviewed.value=false;}
async function save(){if(!file.value||busy.value||!reviewed.value)return;busy.value=true;message.value='';try{const data=new FormData();data.append('image',file.value);data.append('version',String(version.value));data.append('reviewed','true');const r=await fetch('/platform/branding',{method:'POST',body:data,credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??''},signal:AbortSignal.timeout(25000)});const v=await r.json();if(!r.ok)throw Error(v.code??String(r.status));version.value=v.version;file.value=null;message.value=tr('Logo diterbitkan. Muat ulang halaman untuk melihatnya.','Logo published. Reload the page to see it.');}catch{message.value=tr('Belum tersimpan. Pastikan verifikasi keamanan masih berlaku, lalu coba lagi.','Not saved. Renew security verification and retry.');}finally{busy.value=false;}}
</script>
<template><section class="brand-panel"><h2>{{tr('Identitas platform','Platform identity')}}</h2><p>{{tr('Logo tampil konsisten pada halaman publik dan ruang kerja. Pratinjau dahulu sebelum diterbitkan.','The logo appears across public pages and workspaces. Review before publishing.')}}</p><img v-if="preview" :src="preview" alt="Pratinjau logo oneQay"/><label>{{tr('Unggah logo','Upload logo')}}<input type="file" accept="image/png,image/jpeg,image/webp" @change="choose" :disabled="busy"/></label><label><input v-model="reviewed" type="checkbox" :disabled="!file||busy"/>{{tr('Pratinjau sudah sesuai','Preview looks correct')}}</label><button :disabled="!file||!reviewed||busy" @click="save">{{busy?tr('Menerbitkan…','Publishing…'):tr('Terbitkan logo','Publish logo')}}</button><p role="status">{{message}}</p></section></template>
<style scoped>.brand-panel{padding:24px;border:1px solid #E9EBFF;border-radius:20px;background:#FFFFFF;color:#1B1B39;font:16px/1.6 system-ui;margin:20px 0}.brand-panel img{display:block;max-width:100%;width:200px;height:64px;object-fit:contain;margin:16px 0}.brand-panel label{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:14px 0}.brand-panel input[type=file]{width:100%;max-width:100%;min-width:0}.brand-panel{min-width:0;overflow-wrap:anywhere}.brand-panel button{padding:12px 20px;background:#3965FA;color:#FFFFFF;border:0;border-radius:10px;font:600 16px system-ui}.brand-panel button:disabled{opacity:.5}</style>
